// File: src/app/(frontend)/styles.css
```css
/* ====================  MÀU CHỈ ĐỊNH CHÍNH  ==================== */
/* Đặt màu gốc cho toàn bộ giao diện */
:root {
  /* Màu nền chính (black) */
  --bg-primary: #000000;
  /* Màu văn bản chính (white) */
  --text-primary: #ffffff;
  /* Màu nền phụ (để card, panel…) – giữ độ tương phản */
  --bg-secondary: #111111;
  /* Màu viền, hover… */
  --border-color: #333333;
}

/* ====================  BODY & TEXT  ==================== */
body {
  color: var(--text-primary);
  background-color: var(--bg-primary);
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

/* Các thành phần text */
.text-primary {
  color: var(--text-primary);
}

/* ====================  BACKGROUND ==================== */
.bg-primary {
  background-color: var(--bg-primary);
}

/* ====================  BUTTONS ==================== */
.btn-primary {
  display: inline-block;
  padding: 0.5rem 1rem;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 0.25rem;
  cursor: pointer;
  transition: background-color 0.2s ease;
}
.btn-primary:hover {
  background-color: #111111; /* đậm hơn một chút để tạo hiệu ứng hover */
}

/* ====================  CARDS & PANELS ==================== */
.card {
  background-color: var(--bg-secondary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 1rem;
}

/* ====================  HEADERS / FOOTERS ==================== */
.SiteHeader,
.SiteFooter {
  background-color: var(--bg-primary);
  color: var(--text-primary);
}

/* ====================  FORM CONTROLS ==================== */
input,
select,
textarea {
  background-color: var(--bg-secondary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 0.25rem;
  padding: 0.5rem;
}

/* ====================  UTILITIES ==================== */
.text-white {
  color: var(--text-primary) !important;
}
.bg-white {
  background-color: var(--text-primary) !important;
}
```

