import { FC } from 'react';

type ButtonProps = {
  children: React.ReactNode;
  className?: string;
};

export const Button: FC<ButtonProps> = ({ children, className }) => {
  return (
    <button
      className={`btn-primary ${className || ''}`}
      type="button"
    >
      {children}
    </button>
  );
};
```

