// File: src/app/(frontend)/styles.css
@import 'tailwindcss';

@theme {
  --font-sans: var(--font-be-vietnam), 'Be Vietnam Pro', 'Inter', ui-sans-serif, system-ui,
    sans-serif;

  --color-canvas: #f7f8fc;
  --color-ink: #000000;   // ✅ Changed from #172033 to #000000

  --color-brand-50: #eef0ff;
  --color-brand-100: #e0e3ff;
  --color-brand-200: #c6caff;
  --color-brand-300: #a3a7fb;
  --color-brand-400: #8586f2;
  --color-brand-500: #6d6ee8;
  --color-brand-600: #5b5ce2;
  --color-brand-700: #4b4cc9;
  --color-brand-800: #3e3fa8;
  --color-brand-900: #35378a;
}

@layer base {
  html {
    scroll-behavior: smooth;
  }

  body {
    min-height: 100vh;
    font-family: var(--font-sans);
    background: var(--color-canvas);
    color: var(--color-ink);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  button,
  [role='button'] {
    cursor: pointer;
  }

  :focus-visible {
    outline: 2px solid var(--color-brand-600);
    outline-offset: 2px;
  }

  ::selection {
    background: var(--color-brand-200);
    color: var(--color-ink);
  }
}

